+			name: "no_supported_channel_creds",
+			json: `{"dns:///sharding-service:443": {"channel_creds": [{"type": "unsupported_cred_type"}]}}`,
+		},
+		{
+			name: "null_entry",
+			json: `{"dns:///sharding-service:443": null}`,
+		},
+	}
